function upCsv(){let f=document.getElementById('csv').files[0];if(!f)return;showToast('A importar CSV de Faltantes...',!0);let r=new FileReader();r.onload=e=>{if(isAppsScript){google.script.run.withSuccessHandler(()=>{document.getElementById('csv').value='';showToast('CSV importado! A processar cálculos da planilha...',!0);setTimeout(run,3000)}).withFailureHandler(err=>{showToast('Erro no upload: '+err.message,!1);document.getElementById('csv').value=''}).uploadCsvFaltantes(e.target.result)}else{setTimeout(()=>{showToast('CSV importado Fake',!0);run()},500)}};r.readAsText(f)}
function run(){document.getElementById('grid').innerHTML='<div class="col-span-full flex flex-col items-center justify-center p-20 text-ml-blue font-bold"><div class="w-10 h-10 border-4 border-ml-blue border-t-transparent rounded-full animate-spin mb-4"></div>A cruzar planilhas e atualizar base local...</div>';if(isAppsScript){google.script.run.withSuccessHandler(r=>{if(r.syncSuccess===false)showToast("Aviso Sync: "+r.syncMsg,!1);rd=r.rotas;ff=r.faltantes;usr=r.userEmail;document.getElementById('userEmail').innerText=usr;render()}).withFailureHandler(e=>{showToast("Erro GERAL: "+e.message,!1);document.getElementById('grid').innerHTML=`<div class="col-span-full text-center text-red-500 font-bold p-10 tracking-widest uppercase">FALHA NA LEITURA: ${e.message}</div>`}).processarBingo()}else{setTimeout(()=>{rd={'123':{rota:'123',statusRota:'Liberado',conferente:'Bruno'}};ff=[{id:'pkg1',rota:'123'}];render()},500)}}
function render(){let h='',s=document.getElementById('search').value.toLowerCase().trim(),g={};ff.forEach(f=>{let rt=f.rota||'SEM_ROTA';if(!g[rt])g[rt]={rt:rt,pkgs:[],bd:{}};g[rt].pkgs.push(f);if(rd[f.id])g[rt].bd=rd[f.id]});Object.values(rd).forEach(r=>{let rt=r.rota;if(rt&&!g[rt])g[rt]={rt:rt,pkgs:[],bd:r}});let arr=Object.values(g).sort((a,b)=>a.rt.localeCompare(b.rt));if(s)arr=arr.filter(x=>x.rt.toLowerCase().includes(s)||x.pkgs.some(p=>p.id.toLowerCase().includes(s)));if(arr.length===0){document.getElementById('grid').innerHTML='<div class="col-span-full text-center text-gray-400 font-bold p-10 tracking-widest uppercase">Nenhum resultado encontrado.</div>';return}arr.forEach(x=>{let b=x.bd||{},st=b.statusRota||'Pendente',cn=b.conferente||'Atribuir Conferente',bc=st==='Liberado'?'border-ml-green':(st==='Auditando'?'border-ml-blue':(st==='Finalizado'?'border-purple-500':'border-gray-300')),bgc=st==='Finalizado'?'bg-gray-50 opacity-75':'bg-white';let pkgsHtml=x.pkgs.map(p=>{let ps=rd[p.id]?rd[p.id].statusId:'Pendente';return`<div class="flex justify-between items-center bg-gray-50 p-2 rounded border border-gray-100 text-[11px] mb-1.5"><span class="font-black text-ml-blue truncate w-1/2" title="${p.id}">${p.id}</span><select id="st_pkg_${p.id}" class="ml-inp h-[24px] text-[10px] w-[90px] p-0 px-1 font-bold text-gray-700 bg-white shadow-sm border-gray-200 focus:border-ml-blue"><option ${ps==='Pendente'?'selected':''}>Pendente</option><option ${ps==='Faltante'?'selected':''}>Faltante</option><option ${ps==='Bipado'?'selected':''}>Bipado</option><option ${ps==='Bingo'?'selected':''}>Bingo</option></select></div>`}).join('');h+=`<div class="andes-card to-print ${bgc} border-l-4 ${bc} flex flex-col gap-2 relative transition-all hover:shadow-md"><div class="flex justify-between items-center border-b border-gray-100 pb-2"><div class="flex flex-col"><span class="text-[9px] font-bold text-gray-400 uppercase tracking-widest mb-0.5">Rota / Rota PL</span><h3 class="font-black text-[16px] text-ml-dark leading-none">${x.rt}</h3></div><span class="bg-gray-100 border border-gray-200 px-2 py-1 rounded text-[10px] font-bold text-gray-600 shadow-sm">${x.pkgs.length} Pacotes</span></div><div class="grid grid-cols-2 gap-2 mt-1"><select id="st_${x.rt}" class="ml-inp h-[30px] text-[11px] font-bold text-gray-700 bg-gray-50 cursor-pointer shadow-sm border-gray-200 focus:border-ml-blue transition"><option ${st==='Pendente'?'selected':''}>Pendente</option><option ${st==='Auditando'?'selected':''}>Auditando</option><option ${st==='Liberado'?'selected':''}>Liberado</option><option ${st==='Finalizado'?'selected':''}>Finalizado</option></select><button onclick="openC('${x.rt}')" class="andes-button andes-button--transparent h-[30px] text-[10px] truncate w-full shadow-sm bg-white px-1" title="${cn}">${cn}</button></div><div class="flex gap-2"><input type="text" id="vl_${x.rt}" placeholder="Valor" value="${b.valor||''}" class="ml-inp h-[30px] w-[60px] text-center text-[11px] font-bold shadow-sm"><input type="text" id="ob_${x.rt}" placeholder="Observações/Rota Original..." value="${b.obs||''}" class="ml-inp h-[30px] flex-1 text-[11px] shadow-sm"></div><button onclick="saveR('${x.rt}')" class="andes-button andes-button--quiet w-full text-[11px] h-[30px] bg-blue-50/50 hover:bg-blue-50 font-bold border border-transparent hover:border-blue-200 mt-1 mb-1">Guardar Alterações da Rota</button><div class="flex flex-col max-h-[150px] overflow-y-auto custom-scrollbar pr-1 border-t border-gray-100 pt-2">${pkgsHtml||'<span class="text-[10px] text-gray-400 text-center italic mt-2">Bingo Manual. Sem pacotes associados.</span>'}</div></div>`});document.getElementById('grid').innerHTML=h}
function saveR(rt){let st=document.getElementById('st_'+rt).value,vl=document.getElementById('vl_'+rt).value,ob=document.getElementById('ob_'+rt).value,pks=ff.filter(f=>f.rota===rt),up=[],cn='';Object.values(rd).forEach(r=>{if(r.rota===rt&&r.conferente)cn=r.conferente});if(pks.length>0){pks.forEach(p=>{let pSt=document.getElementById('st_pkg_'+p.id)?document.getElementById('st_pkg_'+p.id).value:'Pendente';up.push({isNewBingo:!rd[p.id],id:p.id,rota:rt,valor:vl,conteudo:rd[p.id]?rd[p.id].conteudo:'',statusRota:st,statusId:pSt,conferente:cn,obs:ob})})}else{up.push({isNewBingo:!rd[rt],id:rt,rota:rt,valor:vl,conteudo:rd[rt]?rd[rt].conteudo:'',statusRota:st,statusId:'Pendente',conferente:cn,obs:ob})}sync(up);showToast('Status e Pacotes Guardados!');up.forEach(u=>rd[u.id]=u);render()}
function sync(u){syncs++;updIco();if(isAppsScript){google.script.run.withSuccessHandler(()=>{syncs--;updIco()}).withFailureHandler(e=>{syncs--;updIco();showToast('Erro: '+e.message,!1)}).syncUpdates(u)}else{setTimeout(()=>{syncs--;updIco()},500)}}
function updIco(){let e=document.getElementById('syncIcon');if(syncs>0){e.innerHTML='<span class="animate-spin inline-block mr-1">⏳</span> A Guardar...';e.className='text-[11px] font-bold text-orange-500 flex items-center'}else{e.innerHTML='✅ Atualizado';e.className='text-[11px] font-bold text-ml-green flex items-center'}}
function openM(id){document.getElementById(id).style.display='flex'}
function closeM(id){document.getElementById(id).style.display='none'}
function openC(rt){document.getElementById('cRota').value=rt;document.getElementById('cNome').value='';Object.values(rd).forEach(r=>{if(r.rota===rt&&r.conferente)document.getElementById('cNome').value=r.conferente});openM('cMdl')}
function saveC(){let rt=document.getElementById('cRota').value,n=document.getElementById('cNome').value;Object.values(rd).forEach(r=>{if(r.rota===rt)r.conferente=n});if(!rd[rt])rd[rt]={rota:rt,conferente:n};if(isAppsScript)google.script.run.salvarConfMdl(rt,n);showToast('Conferente atribuído à Rota!');closeM('cMdl');render()}
function saveB(){let r=document.getElementById('bRotapl').value.trim(),o=document.getElementById('bObs').value.trim();if(!r)return showToast('Insira a Rota Atual!',!1);if(isAppsScript){google.script.run.withSuccessHandler(res=>{rd=res.rotas;ff=res.faltantes;showToast('Bingo Manual Inserido!');closeM('bMdl');render()}).salvarBingoManual(r,o)}}
function openX(t){openM('xMdl');document.getElementById('xTitle').innerText='RAIO-X: '+t.toUpperCase();document.getElementById('xHead').innerHTML='';document.getElementById('xBody').innerHTML='';document.getElementById('xLoad').style.display='block';if(isAppsScript){google.script.run.withSuccessHandler(r=>{rawX=r;document.getElementById('xLoad').style.display='none';viewX(t)}).withFailureHandler(e=>{showToast("Erro: "+e.message,!1);document.getElementById('xLoad').innerText='ERRO: '+e.message;document.getElementById('xLoad').style.color='red'}).debugBingoTabelas()}else{setTimeout(()=>{rawX={faltantes:[['ID','ROTA'],['1','A']],bingo:[['ID','ST'],['1','OK']],bingoFaltante:[['ID','OBS'],['1','...']]};document.getElementById('xLoad').style.display='none';viewX(t)},500)}}
function viewX(t){if(!rawX[t])return;let d=rawX[t],h='',b='';if(d.length>0){h='<tr>'+d[0].map(x=>`<th class="p-2 border-r border-gray-200 text-gray-500 font-black tracking-widest uppercase">${x}</th>`).join('')+'</tr>';for(let i=1;i<d.length;i++)b+=`<tr class="hover:bg-blue-50/50">${d[i].map(x=>`<td class="p-2 border-r border-gray-100 text-gray-700">${x!==null&&x!==undefined?x:''}</td>`).join('')}</tr>`}document.getElementById('xHead').innerHTML=h;document.getElementById('xBody').innerHTML=b}
window._init_bingo=run;
